<?php require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("UPDATE settings SET business_name=?,phone=?,email=?,address=?,receipt_footer=? WHERE id=1");$s->execute([$_POST['business_name'],$_POST['phone'],$_POST['email'],$_POST['address'],$_POST['receipt_footer']]);$saved=true;}
$s=$pdo->query("SELECT * FROM settings WHERE id=1")->fetch();
